    73→        type.createAndRegister("LIFECYCLE_STATE_UNSPECIFIED");
    74→
    75→    /** The normal and active state. */
    76→    public static final State ACTIVE = type.createAndRegister("ACTIVE");
    77→
    78→    /**
    79→     * The project has been marked for deletion by the user or by the system (Google Cloud
    80→     * Platform). This can generally be reversed by calling {@link ResourceManager#undelete}.
    81→     */
    82→    public static final State DELETE_REQUESTED = type.createAndRegister("DELETE_REQUESTED");
    83→
    84→    /**
    85→     * The process of deleting the project has begun. Reversing the deletion is no longer possible.
    86→     */
    87→    public static final State DELETE_IN_PROGRESS = type.createAndRegister("DELETE_IN_PROGRESS");
    88→
    89→    private State(String constant) {
    90→      super(constant);
    91→    }
    92→
    93→    /**
    94→     * Get the State for the given String constant, and throw an exception if the constant is not
    95→     * recognized.
    96→     */
