   112→  public static class ResourceId implements Serializable {
   113→
   114→    private static final long serialVersionUID = -325199985993344726L;
   115→
   116→    private final String id;
   117→    private final String type;
   118→
   119→    ResourceId(String id, String type) {
   120→      this.id = checkNotNull(id);
   121→      this.type = checkNotNull(type);
   122→    }
   123→
   124→    public static ResourceId of(String id, String type) {
   125→      return new ResourceId(checkNotNull(id), checkNotNull(type));
   126→    }
   127→
   128→    public String getId() {
