   191→  private class RequestHandler implements HttpHandler {
   192→    @Override
   193→    public void handle(HttpExchange exchange) {
   194→      // see https://cloud.google.com/resource-manager/reference/rest/
   195→      Response response;
   196→      String path = BASE_CONTEXT.relativize(exchange.getRequestURI()).getPath();
   197→      String requestMethod = exchange.getRequestMethod();
   198→      try {
   199→        switch (requestMethod) {
   200→          case "POST":
   201→            response = handlePost(exchange, path);
   202→            break;
   203→          case "DELETE":
   204→            response = delete(projectIdFromUri(path));
   205→            break;
   206→          case "GET":
   207→            if (!path.isEmpty()) {
   208→              response =
   209→                  get(projectIdFromUri(path), parseFields(exchange.getRequestURI().getQuery()));
   210→            } else {
   211→              response = list(parseListOptions(exchange.getRequestURI().getQuery()));
   212→            }
   213→            break;
   214→          case "PUT":
   215→            String requestBody =
   216→                decodeContent(exchange.getRequestHeaders(), exchange.getRequestBody());
   217→            response =
   218→                replace(projectIdFromUri(path), jsonFactory.fromString(requestBody, Project.class));
   219→            break;
   220→          default:
   221→            response =
   222→                Error.BAD_REQUEST.response(
   223→                    "The server could not understand the following request URI: "
   224→                        + requestMethod
   225→                        + " "
   226→                        + path);
   227→        }
   228→      } catch (IOException e) {
   229→        response = Error.BAD_REQUEST.response(e.getMessage());
   230→      }
   231→      writeResponse(exchange, response);
   232→    }
   233→  }
