   235→  private Response handlePost(HttpExchange exchange, String path) throws IOException {
   236→    String requestBody = decodeContent(exchange.getRequestHeaders(), exchange.getRequestBody());
   237→    if (!path.contains(":")) {
   238→      return create(jsonFactory.fromString(requestBody, Project.class));
   239→    } else {
   240→      switch (path.split(":", 2)[1]) {
   241→        case "undelete":
   242→          return undelete(projectIdFromUri(path));
   243→        case "getIamPolicy":
   244→          return getPolicy(projectIdFromUri(path));
   245→        case "setIamPolicy":
   246→          return replacePolicy(
   247→              projectIdFromUri(path),
   248→              jsonFactory.fromString(requestBody, SetIamPolicyRequest.class).getPolicy());
   249→        case "testIamPermissions":
   250→          return testPermissions(
   251→              projectIdFromUri(path),
   252→              jsonFactory
   253→                  .fromString(requestBody, TestIamPermissionsRequest.class)
   254→                  .getPermissions());
   255→        default:
   256→          return Error.BAD_REQUEST.response(
   257→              "The server could not understand the following request URI: POST " + path);
   258→      }
   259→    }
   260→  }
