   304→  private static void writeResponse(HttpExchange exchange, Response response) {
   305→    exchange.getResponseHeaders().set("Content-type", "application/json; charset=UTF-8");
   306→    OutputStream outputStream = exchange.getResponseBody();
   307→    try {
   308→      exchange.getResponseHeaders().add("Connection", "close");
   309→      exchange.sendResponseHeaders(response.code(), response.body().length());
   310→      outputStream.write(response.body().getBytes(StandardCharsets.UTF_8));
   311→      outputStream.close();
   312→    } catch (IOException e) {
   313→      log.log(Level.WARNING, "IOException encountered when sending response.", e);
   314→    }
   315→  }
