   317→  private static String decodeContent(Headers headers, InputStream inputStream) throws IOException {
   318→    List<String> contentEncoding = headers.get("Content-encoding");
   319→    InputStream input = inputStream;
   320→    try {
   321→      if (contentEncoding != null && !contentEncoding.isEmpty()) {
   322→        String encoding = contentEncoding.get(0);
   323→        if (SUPPORTED_COMPRESSION_ENCODINGS.contains(encoding)) {
   324→          input = new GZIPInputStream(inputStream);
   325→        } else if (!encoding.equals("identity")) {
   326→          throw new IOException(
   327→              "The request has the following unsupported HTTP content encoding: " + encoding);
   328→        }
   329→      }
   330→      return new String(ByteStreams.toByteArray(input), StandardCharsets.UTF_8);
   331→    } catch (IOException e) {
   332→      throw new IOException("Exception encountered when decoding request content.", e);
   333→    }
   334→  }
