   336→  private static String projectIdFromUri(String path) throws IOException {
   337→    if (path.isEmpty()) {
   338→      throw new IOException("The URI path '" + path + "' doesn't have a project ID.");
   339→    }
   340→    return path.split(":")[0];
   341→  }
