   343→  private static String[] parseFields(String query) {
   344→    if (query != null && !query.isEmpty()) {
   345→      String[] querySplit = query.split("=");
   346→      return querySplit.length > 1 ? querySplit[1].split(",") : null;
   347→    }
   348→    return null;
   349→  }
   350→
   351→  private static Map<String, Object> parseListOptions(String query) throws IOException {
   352→    Map<String, Object> options = new HashMap<>();
   353→    if (query != null) {
   354→      String[] args = query.split("&");
   355→      for (String arg : args) {
   356→        String[] argEntry = arg.split("=");
   357→        switch (argEntry[0]) {
   358→          case "fields":
   359→            // List fields are in the form "projects(field1, field2, ...),nextPageToken"
   360→            Matcher matcher = LIST_FIELDS_PATTERN.matcher(argEntry[1]);
   361→            if (matcher.matches()) {
   362→              options.put("projectFields", matcher.group(2).split(","));
   363→              options.put("listFields", (matcher.group(1) + matcher.group(3)).split(","));
   364→            } else {
   365→              options.put("projectFields", NO_FIELDS);
   366→              options.put("listFields", argEntry[1].split(","));
   367→            }
   368→            break;
   369→          case "filter":
   370→            options.put("filter", argEntry[1].split(" "));
   371→            break;
   372→          case "pageToken":
   373→            options.put("pageToken", argEntry[1]);
   374→            break;
   375→          case "pageSize":
   376→            int pageSize = Integer.parseInt(argEntry[1]);
   377→            if (pageSize < 1) {
   378→              throw new IOException("Page size must be greater than 0.");
   379→            }
   380→            options.put("pageSize", pageSize);
   381→            break;
   382→        }
   383→      }
   384→    }
   385→    return options;
   386→  }
