   388→  private static String checkForProjectErrors(Project project) {
   389→    if (project.getProjectId() == null) {
   390→      return "Project ID cannot be empty.";
   391→    }
   392→    if (!isValidIdOrLabel(project.getProjectId(), 6, 30)) {
   393→      return "Project "
   394→          + project.getProjectId()
   395→          + " has an invalid ID."
   396→          + " See https://cloud.google.com/resource-manager/reference/rest/"
   397→          + VERSION
   398→          + "/projects"
   399→          + " for more information.";
   400→    }
   401→    if (project.getName() != null) {
   402→      for (char c : project.getName().toCharArray()) {
   403→        if (!PERMISSIBLE_PROJECT_NAME_PUNCTUATION.contains(c) && !Character.isLetterOrDigit(c)) {
   404→          return "Project "
   405→              + project.getProjectId()
   406→              + " has an invalid name."
   407→              + " See https://cloud.google.com/resource-manager/reference/rest/"
   408→              + VERSION
   409→              + "/projects for more information.";
   410→        }
   411→      }
   412→    }
   413→    if (project.getLabels() != null) {
   414→      if (project.getLabels().size() > 256) {
   415→        return "Project " + project.getProjectId() + " exceeds the limit of 256 labels.";
   416→      }
   417→      for (Map.Entry<String, String> entry : project.getLabels().entrySet()) {
   418→        if (!isValidIdOrLabel(entry.getKey(), 1, 63)
   419→            || !isValidIdOrLabel(entry.getValue(), 0, 63)) {
   420→          return "Project "
   421→              + project.getProjectId()
   422→              + " has an invalid label entry."
   423→              + " See https://cloud.google.com/resource-manager/reference/rest/"
   424→              + VERSION
   425→              + "/projects for more information.";
   426→        }
   427→      }
   428→    }
   429→    return null;
   430→  }
   431→
   432→  private static boolean isValidIdOrLabel(String value, int minLength, int maxLength) {
   433→    for (char c : value.toCharArray()) {
   434→      if (c != '-' && !Character.isDigit(c) && !Character.isLowerCase(c)) {
   435→        return false;
   436→      }
   437→    }
   438→    if (!value.isEmpty() && (!Character.isLetter(value.charAt(0)) || value.endsWith("-"))) {
   439→      return false;
   440→    }
   441→    return value.length() >= minLength && value.length() <= maxLength;
   442→  }
