   444→  synchronized Response create(Project project) {
   445→    String customErrorMessage = checkForProjectErrors(project);
   446→    if (customErrorMessage != null) {
   447→      return Error.INVALID_ARGUMENT.response(customErrorMessage);
   448→    } else {
   449→      project.setLifecycleState("ACTIVE");
   450→      project.setProjectNumber(Math.abs(PROJECT_NUMBER_GENERATOR.nextLong() % Long.MAX_VALUE));
   451→      project.setCreateTime(
   452→          DateTimeFormatter.ISO_DATE_TIME
   453→              .withZone(ZoneOffset.UTC)
   454→              .format(Instant.ofEpochMilli(System.currentTimeMillis())));
   455→      if (projects.putIfAbsent(project.getProjectId(), project) != null) {
   456→        return Error.ALREADY_EXISTS.response(
   457→            "A project with the same project ID (" + project.getProjectId() + ") already exists.");
   458→      }
   459→      Policy emptyPolicy =
   460→          new Policy()
   461→              .setBindings(Collections.<Binding>emptyList())
   462→              .setEtag(UUID.randomUUID().toString())
   463→              .setVersion(0);
   464→      policies.put(project.getProjectId(), emptyPolicy);
   465→      try {
   466→        // Pretend it's not done yet.
   467→        String createdProjectStr =
   468→            jsonFactory.toString(
   469→                new Operation().setDone(false).setName("operations/" + project.getProjectId()));
   470→        return new Response(HTTP_OK, createdProjectStr);
   471→      } catch (IOException e) {
   472→        return Error.INTERNAL_ERROR.response("Error serializing project " + project.getProjectId());
   473→      }
   474→    }
   475→  }
