   477→  synchronized Response delete(String projectId) {
   478→    Project project = projects.get(projectId);
   479→    if (project == null) {
   480→      return Error.PERMISSION_DENIED.response(
   481→          "Error when deleting " + projectId + " because the project was not found.");
   482→    }
   483→    if (!project.getLifecycleState().equals("ACTIVE")) {
   484→      return Error.FAILED_PRECONDITION.response(
   485→          "Error when deleting " + projectId + " because the lifecycle state was not ACTIVE.");
   486→    } else {
   487→      project.setLifecycleState("DELETE_REQUESTED");
   488→      return new Response(HTTP_OK, "{}");
   489→    }
   490→  }
