   492→  Response get(String projectId, String[] fields) {
   493→    Project project = projects.get(projectId);
   494→    if (project != null) {
   495→      try {
   496→        return new Response(HTTP_OK, jsonFactory.toString(extractFields(project, fields)));
   497→      } catch (IOException e) {
   498→        return Error.INTERNAL_ERROR.response(
   499→            "Error when serializing project " + project.getProjectId());
   500→      }
   501→    } else {
