   505→
   506→  Response list(Map<String, Object> options) {
   507→    List<String> projectsSerialized = new ArrayList<>();
   508→    String[] filters = (String[]) options.get("filter");
   509→    if (filters != null && !isValidFilter(filters)) {
   510→      return Error.INVALID_ARGUMENT.response("Could not parse the filter.");
   511→    }
   512→    String[] projectFields = (String[]) options.get("projectFields");
   513→    int count = 0;
   514→    String pageToken = (String) options.get("pageToken");
   515→    Integer pageSize = (Integer) options.get("pageSize");
   516→    String nextPageToken = null;
   517→    Map<String, Project> projectsToScan = projects;
   518→    if (pageToken != null) {
   519→      projectsToScan = projects.tailMap(pageToken);
   520→    }
   521→    for (Project p : projectsToScan.values()) {
   522→      if (pageSize != null && count >= pageSize) {
   523→        nextPageToken = p.getProjectId();
   524→        break;
   525→      }
   526→      boolean includeProject = includeProject(p, filters);
   527→      if (includeProject) {
   528→        count++;
   529→        try {
   530→          projectsSerialized.add(jsonFactory.toString(extractFields(p, projectFields)));
   531→        } catch (IOException e) {
   532→          return Error.INTERNAL_ERROR.response(
   533→              "Error when serializing project " + p.getProjectId());
   534→        }
   535→      }
   536→    }
   537→    String[] listFields = (String[]) options.get("listFields");
   538→    StringBuilder responseBody = new StringBuilder();
   539→    responseBody.append('{');
   540→    // If fields parameter is set but no project field is selected we must return no projects.
   541→    if (!(projectFields != null && projectFields.length == 0)) {
   542→      responseBody.append("\"projects\": [");
   543→      Joiner.on(",").appendTo(responseBody, projectsSerialized);
   544→      responseBody.append(']');
   545→    }
   546→    if (nextPageToken != null
   547→        && (listFields == null || ImmutableSet.copyOf(listFields).contains("nextPageToken"))) {
   548→      if (responseBody.length() > 1) {
   549→        responseBody.append(',');
   550→      }
   551→      responseBody.append("\"nextPageToken\": \"");
   552→      responseBody.append(nextPageToken);
   553→      responseBody.append('"');
   554→    }
   555→    responseBody.append('}');
   556→    return new Response(HTTP_OK, responseBody.toString());
   557→  }
   558→
   559→  private static boolean isValidFilter(String[] filters) {
   560→    for (String filter : filters) {
   561→      String field = filter.toLowerCase().split(":")[0];
   562→      if (!("id".equals(field) || "name".equals(field) || field.startsWith("labels."))) {
   563→        return false;
   564→      }
   565→    }
   566→    return true;
   567→  }
   568→
   569→  private static boolean includeProject(Project project, String[] filters) {
   570→    if (filters == null) {
   571→      return true;
   572→    }
   573→    for (String filter : filters) {
   574→      String[] filterEntry = filter.toLowerCase().split(":");
   575→      String filterType = filterEntry[0];
   576→      if ("id".equals(filterType)) {
   577→        if (!satisfiesFilter(project.getProjectId(), filterEntry[1])) {
   578→          return false;
   579→        }
   580→      } else if ("name".equals(filterType)) {
   581→        if (!satisfiesFilter(project.getName(), filterEntry[1])) {
   582→          return false;
   583→        }
   584→      } else if (filterType.startsWith("labels.")) {
   585→        String labelKey = filterType.substring("labels.".length());
   586→        if (project.getLabels() != null) {
   587→          String labelValue = project.getLabels().get(labelKey);
   588→          if (!satisfiesFilter(labelValue, filterEntry[1])) {
   589→            return false;
   590→          }
   591→        }
   592→      }
   593→    }
   594→    return true;
   595→  }
   596→
   597→  private static boolean satisfiesFilter(String projectValue, String filterValue) {
   598→    if (projectValue == null) {
   599→      return false;
   600→    }
   601→    return "*".equals(filterValue) || filterValue.equals(projectValue.toLowerCase());
   602→  }
   603→
   604→  private static Project extractFields(Project fullProject, String[] fields) {
   605→    if (fields == null) {
   606→      return fullProject;
   607→    }
   608→    Project project = new Project();
   609→    for (String field : fields) {
   610→      switch (field) {
   611→        case "createTime":
   612→          project.setCreateTime(fullProject.getCreateTime());
   613→          break;
   614→        case "labels":
   615→          project.setLabels(fullProject.getLabels());
   616→          break;
   617→        case "lifecycleState":
   618→          project.setLifecycleState(fullProject.getLifecycleState());
   619→          break;
   620→        case "name":
   621→          project.setName(fullProject.getName());
   622→          break;
   623→        case "parent":
   624→          project.setParent(fullProject.getParent());
   625→          break;
   626→        case "projectId":
   627→          project.setProjectId(fullProject.getProjectId());
   628→          break;
   629→        case "projectNumber":
   630→          project.setProjectNumber(fullProject.getProjectNumber());
   631→          break;
   632→      }
   633→    }
   634→    return project;
   635→  }
