   637→  synchronized Response replace(String projectId, Project project) {
   638→    Project originalProject = projects.get(projectId);
   639→    if (originalProject == null) {
   640→      return Error.PERMISSION_DENIED.response(
   641→          "Error when replacing " + projectId + " because the project was not found.");
   642→    } else if (!originalProject.getLifecycleState().equals("ACTIVE")) {
   643→      return Error.FAILED_PRECONDITION.response(
   644→          "Error when replacing " + projectId + " because the lifecycle state was not ACTIVE.");
   645→    } else if (!Objects.equal(originalProject.getParent(), project.getParent())) {
   646→      return Error.INVALID_ARGUMENT.response(
   647→          "The server currently only supports setting the parent once "
   648→              + "and does not allow unsetting it.");
   649→    }
   650→    project.setProjectId(projectId);
   651→    project.setLifecycleState(originalProject.getLifecycleState());
   652→    project.setCreateTime(originalProject.getCreateTime());
   653→    project.setProjectNumber(originalProject.getProjectNumber());
   654→    // replace cannot fail because both this method and removeProject are synchronized
   655→    projects.replace(projectId, project);
   656→    try {
   657→      return new Response(HTTP_OK, jsonFactory.toString(project));
   658→    } catch (IOException e) {
   659→      return Error.INTERNAL_ERROR.response("Error when serializing project " + projectId);
   660→    }
   661→  }
   662→
   663→  synchronized Response undelete(String projectId) {
   664→    Project project = projects.get(projectId);
   665→    Response response;
   666→    if (project == null) {
   667→      response =
   668→          Error.PERMISSION_DENIED.response(
   669→              "Error when undeleting " + projectId + " because the project was not found.");
   670→    } else if (!project.getLifecycleState().equals("DELETE_REQUESTED")) {
   671→      response =
   672→          Error.FAILED_PRECONDITION.response(
   673→              "Error when undeleting "
   674→                  + projectId
   675→                  + " because the lifecycle state was not DELETE_REQUESTED.");
   676→    } else {
   677→      project.setLifecycleState("ACTIVE");
   678→      response = new Response(HTTP_OK, "{}");
   679→    }
   680→    return response;
   681→  }
   682→
   683→  synchronized Response getPolicy(String projectId) {
   684→    Policy policy = policies.get(projectId);
   685→    if (policy == null) {
   686→      return Error.PERMISSION_DENIED.response("Project " + projectId + " not found.");
   687→    }
   688→    try {
   689→      return new Response(HTTP_OK, jsonFactory.toString(policy));
   690→    } catch (IOException e) {
   691→      return Error.INTERNAL_ERROR.response(
   692→          "Error when serializing the IAM policy for " + projectId);
   693→    }
   694→  }
   695→
   696→  synchronized Response replacePolicy(String projectId, Policy policy) {
   697→    Policy originalPolicy = policies.get(projectId);
   698→    if (originalPolicy == null) {
   699→      return Error.PERMISSION_DENIED.response(
   700→          "Error when replacing the policy for "
   701→              + projectId
   702→              + " because the project was not found.");
   703→    }
   704→    String etag = policy.getEtag();
   705→    if (etag != null && !originalPolicy.getEtag().equals(etag)) {
   706→      return Error.ABORTED.response(
   707→          "Policy etag mismatch when replacing the policy for project "
   708→              + projectId
   709→              + ", please retry the read.");
   710→    }
   711→    policy.setEtag(UUID.randomUUID().toString());
   712→    policy.setVersion(originalPolicy.getVersion());
   713→    policies.put(projectId, policy);
   714→    try {
   715→      return new Response(HTTP_OK, jsonFactory.toString(policy));
   716→    } catch (IOException e) {
   717→      return Error.INTERNAL_ERROR.response(
   718→          "Error when serializing the policy for project " + projectId);
   719→    }
   720→  }
   721→
   722→  synchronized Response testPermissions(String projectId, List<String> permissions) {
   723→    if (!projects.containsKey(projectId)) {
   724→      return Error.PERMISSION_DENIED.response("Project " + projectId + " not found.");
   725→    }
   726→    try {
   727→      return new Response(
   728→          HTTP_OK,
   729→          jsonFactory.toString(new TestIamPermissionsResponse().setPermissions(permissions)));
   730→    } catch (IOException e) {
   731→      return Error.INTERNAL_ERROR.response("Error when serializing permissions " + permissions);
   732→    }
   733→  }
   734→
   735→  private LocalResourceManagerHelper() {
   736→    try {
   737→      server = HttpServer.create(new InetSocketAddress(0), 0);
   738→      port = server.getAddress().getPort();
   739→      server.createContext(CONTEXT, new RequestHandler());
   740→      server.createContext(OPERATION_CONTEXT, new OperationRequestHandler());
   741→    } catch (IOException e) {
   742→      throw new RuntimeException("Could not bind the mock Resource Manager server.", e);
   743→    }
   744→  }
   745→
   746→  /**
   747→   * Creates a {@code LocalResourceManagerHelper} object that listens to requests on the local
   748→   * machine.
   749→   */
   750→  public static LocalResourceManagerHelper create() {
   751→    return new LocalResourceManagerHelper();
   752→  }
   753→
   754→  /**
   755→   * Returns a {@link ResourceManagerOptions} instance that sets the host to use the mock server.
   756→   */
   757→  public ResourceManagerOptions getOptions() {
   758→    return ResourceManagerOptions.newBuilder()
   759→        .setHost("http://localhost:" + port)
   760→        .setCredentials(NoCredentials.getInstance())
   761→        .build();
   762→  }
   763→
   764→  /** Starts the thread that runs the Resource Manager server. */
   765→  public void start() {
   766→    server.start();
   767→  }
   768→
   769→  /** Stops the thread that runs the mock Resource Manager server. */
   770→  public void stop() {
   771→    server.stop(1);
   772→  }
   773→
   774→  /**
   775→   * Utility method to change the lifecycle state of the specified project.
   776→   *
   777→   * @return true if the lifecycle state was successfully updated, false otherwise
   778→   */
   779→  public synchronized boolean changeLifecycleState(String projectId, String lifecycleState) {
   780→    checkArgument(
   781→        "ACTIVE".equals(lifecycleState)
   782→            || "DELETE_REQUESTED".equals(lifecycleState)
   783→            || "DELETE_IN_PROGRESS".equals(lifecycleState),
   784→        "Lifecycle state must be ACTIVE, DELETE_REQUESTED, or DELETE_IN_PROGRESS");
   785→    Project project = projects.get(checkNotNull(projectId));
   786→    if (project != null) {
   787→      project.setLifecycleState(lifecycleState);
   788→      return true;
   789→    }
   790→    return false;
   791→  }
   792→
   793→  /**
   794→   * Utility method to remove the specified project.
   795→   *
   796→   * <p>This method can be used to fully remove a project (to mimic when the server completely
   797→   * deletes a project).
   798→   *
   799→   * @return true if the project was successfully deleted, false if the project didn't exist
   800→   */
   801→  public synchronized boolean removeProject(String projectId) {
   802→    // Because this method is synchronized, any code that relies on non-atomic read/write operations
   803→    // should not fail if that code is also synchronized.
   804→    policies.remove(checkNotNull(projectId));
   805→    return projects.remove(projectId) != null;
   806→  }
   807→}
